<script setup lang="ts">
import{onMounted,onUnmounted,ref}from'vue';import{request}from'../../api/client';import{message,all}from'../sites/data';import{useAuth}from'../auth/store';import type{Site}from'../sites/contracts';
const auth=useAuth(),accounts=ref<any[]>([]),tokens=ref<any[]>([]),sites=ref<Site[]>([]),offset=ref(0),error=ref(''),notice=ref(''),busy=ref(false),code=ref(''),name=ref(''),role=ref('readonly'),target=ref(''),selected=ref<string[]>([]),actions=ref(['view']),expires=ref(new Date(Date.now()+86400000).toISOString().slice(0,16)),once=ref('');
let secretGeneration=0;function clear(){secretGeneration++;once.value='';code.value=''}
async function load(){accounts.value=[];tokens.value=[];if(auth.actor?.role==='admin')accounts.value=(await request<any>('/accounts?limit=25&offset='+offset.value)).items||[];tokens.value=(await request<any>('/tokens?limit=25&offset='+offset.value)).items||[]}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';once.value='';try{await fn()}catch(e){accounts.value=[];tokens.value=[];error.value=message(e)}finally{code.value='';busy.value=false}}
async function create(){await run(async()=>{const owner=secretGeneration,v=await request('/accounts',{name:name.value,role:role.value,totp_code:code.value});if(owner===secretGeneration)once.value=JSON.stringify(v);await load()})}
async function authority(){await run(async()=>{await request('/accounts/'+target.value+'/authority',{role:role.value,grants:selected.value.map(resource_id=>({kind:'site',resource_id})),totp_code:code.value},'PUT');await load();notice.value='账号权限已更新'})}
async function accountAction(id:string,action:string){await run(async()=>{const owner=secretGeneration,v=await request('/accounts/'+id+'/'+action,{totp_code:code.value});if(action==='reset'&&owner===secretGeneration)once.value=JSON.stringify(v);await load();notice.value='账号操作已提交'})}
async function issue(){await run(async()=>{const owner=secretGeneration,v=await request<any>('/tokens',{totp_code:code.value,actions:actions.value,site_ids:selected.value,expires:new Date(expires.value+'Z').toISOString()});if(owner===secretGeneration)once.value=JSON.stringify(v);await load()})}
async function revoke(id:string){await run(async()=>{await request('/tokens/'+id+'/revoke',{totp_code:code.value});await load();notice.value='Token 已停用'})}
onMounted(()=>{window.addEventListener('pagehide',clear);void run(async()=>{await load();sites.value=await all<Site>('/sites')})});onUnmounted(()=>{clear();window.removeEventListener('pagehide',clear)});
</script><template><section><h1>账号与 API Token</h1><p class="muted">停用、降权和撤销立即影响当前请求。Token 只能缩小账号的动作和站点范围。敏感动作需要新的动态验证码。</p><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><button @click="run(load)" :disabled="busy">刷新账号与 Token</button><section v-if="once" class="panel" data-testid="one-time-account"><h2>一次性资料，请安全保存</h2><pre>{{once}}</pre><button @click="clear">已保存，清除一次性资料</button></section><section class="panel"><h2>安全操作</h2><fieldset :disabled="busy"><label>账号操作动态验证码<input v-model="code" inputmode="numeric" autocomplete="off"></label><label v-for="s in sites" :key="s.id" class="check"><input type="checkbox" v-model="selected" :value="s.id">{{s.name}}</label><template v-if="auth.actor?.role==='admin'"><label>新账号名称<input v-model="name"></label><label>角色<select v-model="role"><option>readonly</option><option>editor</option><option>publisher</option><option>admin</option></select></label><button @click="create" :disabled="!code||!name">创建账号并显示一次性绑定</button><label>修改权限账号<select v-model="target"><option value="">请选择</option><option v-for="a in accounts" :value="a.id" :key="a.id">{{a.name}}</option></select></label><button @click="authority" :disabled="!target||!code">设置角色与所选站点权限</button></template><h3>签发有界 Token</h3><label v-for="action in ['view','edit','publish']" :key="action" class="check"><input type="checkbox" v-model="actions" :value="action">{{action}}</label><label>Token 到期（UTC）<input type="datetime-local" v-model="expires"></label><button @click="issue" :disabled="!code||!selected.length||!actions.length">签发一次性 Token</button></fieldset></section><section v-if="accounts.length" class="panel"><h2>账号列表</h2><p v-for="a in accounts" :key="a.id">{{a.name}} · {{a.role}} · {{a.state}} · 授权版本 {{a.auth_version}} <button :disabled="busy||!code" @click="accountAction(a.id,'reset')">重置绑定</button><button :disabled="busy||!code" @click="accountAction(a.id,'disable')">停用账号</button></p></section><section class="panel" data-testid="tokens"><h2>我的 Token</h2><p v-for="t in tokens" :key="t.id">{{t.id}} · {{t.revoked?'已停用':Date.parse(t.expires)<Date.now()?'已到期':'有效'}} · {{t.actions.join(',')}} · {{t.site_ids.join(',')}} <button :disabled="busy||!code||t.revoked" @click="revoke(t.id)">停用此 Token</button></p><button :disabled="busy||!offset" @click="offset-=25;run(load)">上一页账号</button><button :disabled="busy||(tokens.length<25&&accounts.length<25)" @click="offset+=25;run(load)">下一页账号</button></section></section></template>
